export async function createDocument({ title, content, tags }) {
  const response = await fetch("http://localhost:8080/api/documents", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ title, content, tags }),
  });

  if (!response.ok) {
    throw new Error(`문서 생성 실패: ${response.status}`);
  }

}



export async function fetchDocuments({ tags, lastId, size }) {
  const response = await fetch("http://localhost:8080/documents", {
    method: "GET",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      tags,
      pageState: { lastId, size, hasNext: false },
    }),
  });
  if (!response.ok) throw new Error(`문서 조회 실패: ${response.status}`);
  return response.json();
}
